    "sql": "-- Curated book update: preserve visibility, review state, audiences, images, and ordering.\r\nUPDATE resources SET description='John Eldredge explores how faith, identity, and the desire for a meaningful life shape a man''s heart. Drawing on Scripture, personal stories, and his experience counseling men, he considers the effects of past wounds, fear, and passivity, and invites readers to pursue courage and a closer relationship with God. For an accountability group, the book offers a starting point for honest conversations about purpose, friendship, healing, and the kind of man each member hopes to become.',updated_at=CAST(strftime('%s','now') AS INTEGER)*1000,revision=revision+1 WHERE id='wild-at-heart';\r\nUPDATE resources SET description='Joshua Harris addresses lust and sexual temptation from a Christian perspective, combining candid personal reflection with practical encouragement for pursuing purity. He examines habits and influences that can feed temptation, emphasizes dependence on God''s grace, and encourages readers to develop a personal plan for change. Accountability partners can use the book to discuss boundaries, media choices, recurring struggles, and ways to support one another with honesty and compassion. Its approach is direct without relying on graphic descriptions.',updated_at=CAST(strftime('%s','now') AS INTEGER)*1000,revision=revision+1 WHERE id='not-even-a-hint';\r\nINSERT INTO resources (id,category_id,title,creator,description,url,sort_order,created_at,updated_at,image_key)\r\nSELECT 'connection-codes','books','The Connection Codes: The Blueprint & Tools for Creating the Relationships You Crave',\r\n 'Dr. Glenn Hill and Phyllis Hill, with Echo Hill-Vetter','Dr. Glenn Hill and Phyllis Hill, with Echo Hill-Vetter, introduce practical tools for understanding emotions and building closer relationships. The book explores how disconnection develops and encourages readers to recognize what they are feeling, express it clearly, and listen with curiosity rather than defensiveness. Experience assignments help turn the ideas into conversations and everyday practice. Couples, friends, and accountability partners can use it to explore emotional awareness, communicate needs, and make room for more honest, supportive relationships.',\r\n 'https://shop.bethel.com/products/the-connection-codes',30,CAST(strftime('%s','now') AS INTEGER)*1000,CAST(strftime('%s','now') AS INTEGER)*1000,'/assets/resource-covers/connection-codes.jpg'\r\nWHERE EXISTS(SELECT 1 FROM resource_categories WHERE id='books') AND NOT EXISTS(SELECT 1 FROM resources WHERE id='connection-codes');\r\nINSERT INTO resource_tags (resource_id,tag)\r\nSELECT 'connection-codes',tag FROM (SELECT 'relationships' tag UNION ALL SELECT 'communication' UNION ALL SELECT 'emotions' UNION ALL SELECT 'marriage')\r\nWHERE EXISTS(SELECT 1 FROM resources WHERE id='connection-codes');\r\n"
